const TAU = Math.PI * 2;
const W0 = W(), H0 = H();

function hexToRgb(h) {
  const r = parseInt(h.slice(1,3),16);
  const g = parseInt(h.slice(3,5),16);
  const b = parseInt(h.slice(5,7),16);
  return [r,g,b];
}

const C0 = hexToRgb(PALETTE[0]);
const C1 = hexToRgb(PALETTE[1]);
const C2 = hexToRgb(PALETTE[2]);

// Value noise helpers
const NP = 256;
const perm = new Uint8Array(NP*2);
const src = Array.from({length:NP},(_,i)=>i);
for(let i=NP-1;i>0;i--){const j=Math.random()*(i+1)|0;[src[i],src[j]]=[src[j],src[i]];}
for(let i=0;i<NP*2;i++) perm[i]=src[i%NP];
function fade2(t){return t*t*t*(t*(t*6-15)+10);}
function lerp(a,b,t){return a+t*(b-a);}
function grad(h,x,y){
  const H4=h&3;
  const u=H4<2?x:y, v=H4<2?y:x;
  return ((H4&1)?-u:u)+((H4&2)?-v:v);
}
function noise2(x,y){
  const X=Math.floor(x)&255, Y=Math.floor(y)&255;
  const xf=x-Math.floor(x), yf=y-Math.floor(y);
  const u=fade2(xf), v=fade2(yf);
  const aa=perm[perm[X]+Y], ab=perm[perm[X]+Y+1];
  const ba=perm[perm[X+1]+Y], bb=perm[perm[X+1]+Y+1];
  return lerp(lerp(grad(aa,xf,yf),grad(ba,xf-1,yf),u),
              lerp(grad(ab,xf,yf-1),grad(bb,xf-1,yf-1),u),v);
}

// Particles
const N = 520;
const particles = [];

const CX = W0*0.5, CY = H0*0.5;

for(let i=0;i<N;i++){
  // Distribute in rings with some noise
  const ring = Math.random();
  // 3 rings: inner edge, mid, outer
  let baseR;
  const rng = Math.random();
  if(rng < 0.12) baseR = (0.08 + Math.random()*0.06) * Math.min(W0,H0)*0.5;
  else if(rng < 0.45) baseR = (0.28 + Math.random()*0.18) * Math.min(W0,H0)*0.5;
  else baseR = (0.55 + Math.random()*0.38) * Math.min(W0,H0)*0.5;

  const angle = Math.random()*TAU;
  // Scatter a bit
  const scatter = (Math.random()-0.5)*baseR*0.35;
  const r = baseR + scatter;

  const x = CX + Math.cos(angle)*r;
  const y = CY + Math.sin(angle)*r;

  // Color mix based on distance from center
  const t = Math.min(1, r / (Math.min(W0,H0)*0.5));
  // inner: C2 (light), outer: C1 (gold), far: C0 tint
  let colR, colG, colB;
  if(t < 0.5){
    const tt = t*2;
    colR = lerp(C2[0], C1[0], tt);
    colG = lerp(C2[1], C1[1], tt);
    colB = lerp(C2[2], C1[2], tt);
  } else {
    const tt = (t-0.5)*2;
    colR = lerp(C1[0], C0[0]*1.8, tt);
    colG = lerp(C1[1], C0[1]*1.8, tt);
    colB = lerp(C1[2], C0[2]*1.8, tt);
  }
  colR = Math.min(255, colR);
  colG = Math.min(255, colG);
  colB = Math.min(255, colB);

  // Size: bigger near center, smaller at edges, with variation
  const sizeBase = lerp(2.8, 0.6, t) * (0.5 + Math.random()*1.0);

  // Drift parameters — slow orbital drift
  const orbitSpeed = (Math.random()*0.00018 + 0.00006) * (Math.random()<0.5?1:-1);
  const driftAmp = 0.4 + Math.random()*0.8;
  const driftFreq = 0.3 + Math.random()*0.5;
  const driftPhase = Math.random()*TAU;

  // Noise-field offset
  const noiseOff = Math.random()*100;
  const noiseScale = 0.003 + Math.random()*0.002;
  const noiseSpeed = 0.0004 + Math.random()*0.0003;

  // Twinkle
  const twinkleFreq = 0.4 + Math.random()*1.2;
  const twinklePhase = Math.random()*TAU;
  const baseAlpha = 0.25 + Math.random()*0.55;

  particles.push({
    ox: x, oy: y,
    x, y,
    r: baseR, angle,
    colR: colR|0, colG: colG|0, colB: colB|0,
    size: sizeBase,
    orbitSpeed,
    driftAmp,
    driftFreq,
    driftPhase,
    noiseOff,
    noiseScale,
    noiseSpeed,
    twinkleFreq,
    twinklePhase,
    baseAlpha,
    t0: Math.random()*200
  });
}

// Ray accents — thin bright streaks radiating outward
const RAY_COUNT = 7;
const rays = [];
for(let i=0;i<RAY_COUNT;i++){
  const angle = (i/RAY_COUNT)*TAU + Math.random()*0.3;
  const len = (0.32 + Math.random()*0.22)*Math.min(W0,H0)*0.5;
  const startR = (0.05 + Math.random()*0.08)*Math.min(W0,H0)*0.5;
  rays.push({
    angle,
    len,
    startR,
    speed: (Math.random()*0.00012 + 0.00004)*(Math.random()<0.5?1:-1),
    phase: Math.random()*TAU,
    width: 0.4 + Math.random()*0.7
  });
}

let startTime = null;

function draw(ts){
  if(!startTime) startTime = ts;
  const t = (ts - startTime);

  ctx.clearRect(0, 0, W(), H());

  // Soft radial glow at center
  const glowR = Math.min(W(),H())*0.22;
  const grd = ctx.createRadialGradient(CX, CY, 0, CX, CY, glowR);
  grd.addColorStop(0, `rgba(${C2[0]},${C2[1]},${C2[2]},0.07)`);
  grd.addColorStop(0.5, `rgba(${C1[0]},${C1[1]},${C1[2]},0.04)`);
  grd.addColorStop(1, `rgba(0,0,0,0)`);
  ctx.fillStyle = grd;
  ctx.beginPath();
  ctx.arc(CX, CY, glowR, 0, TAU);
  ctx.fill();

  // Draw rays
  for(let i=0;i<rays.length;i++){
    const ray = rays[i];
    const angle = ray.angle + ray.speed*t;
    const pulse = 0.3 + 0.7*(0.5 + 0.5*Math.sin(t*0.0008 + ray.phase));
    const sx = CX + Math.cos(angle)*ray.startR;
    const sy = CY + Math.sin(angle)*ray.startR;
    const ex = CX + Math.cos(angle)*(ray.startR + ray.len);
    const ey = CY + Math.sin(angle)*(ray.startR + ray.len);
    const grdR = ctx.createLinearGradient(sx,sy,ex,ey);
    grdR.addColorStop(0, `rgba(${C2[0]},${C2[1]},${C2[2]},${0.18*pulse})`);
    grdR.addColorStop(0.4, `rgba(${C1[0]},${C1[1]},${C1[2]},${0.22*pulse})`);
    grdR.addColorStop(1, `rgba(${C1[0]},${C1[1]},${C1[2]},0)`);
    ctx.strokeStyle = grdR;
    ctx.lineWidth = ray.width;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.lineTo(ex, ey);
    ctx.stroke();
  }

  // Update and draw particles
  for(let i=0;i<N;i++){
    const p = particles[i];
    const localT = t + p.t0*10;

    // Orbital drift
    const angle = p.angle + p.orbitSpeed * localT;
    // Noise displacement
    const nx = noise2((p.ox*p.noiseScale) + p.noiseOff, localT*p.noiseSpeed);
    const ny = noise2((p.oy*p.noiseScale) + p.noiseOff + 50, localT*p.noiseSpeed + 10);
    // Radial breathing
    const breathe = Math.sin(localT*p.driftFreq*0.001 + p.driftPhase)*p.driftAmp;

    p.x = CX + Math.cos(angle)*(p.r + breathe) + nx*18;
    p.y = CY + Math.sin(angle)*(p.r + breathe) + ny*18;

    // Twinkle
    const twinkle = 0.5 + 0.5*Math.sin(localT*p.twinkleFreq*0.001 + p.twinklePhase);
    const alpha = p.baseAlpha * (0.4 + 0.6*twinkle);

    // Size pulse
    const sizePulse = p.size * (0.8 + 0.4*twinkle);

    ctx.beginPath();
    ctx.arc(p.x, p.y, sizePulse, 0, TAU);
    ctx.fillStyle = `rgba(${p.colR},${p.colG},${p.colB},${alpha})`;
    ctx.fill();

    // Bright core on larger particles
    if(p.size > 1.8 && twinkle > 0.65){
      ctx.beginPath();
      ctx.arc(p.x, p.y, sizePulse*0.38, 0, TAU);
      ctx.fillStyle = `rgba(${C2[0]},${C2[1]},${C2[2]},${alpha*0.7})`;
      ctx.fill();
    }
  }

  // Outer vignette ring — keep edges lively but not center
  const vigR = Math.min(W(),H())*0.48;
  const vig = ctx.createRadialGradient(CX,CY,vigR*0.45,CX,CY,vigR);
  vig.addColorStop(0, 'rgba(0,0,0,0)');
  vig.addColorStop(1, `rgba(${C0[0]},${C0[1]},${C0[2]},0.18)`);
  ctx.fillStyle = vig;
  ctx.beginPath();
  ctx.arc(CX,CY,vigR,0,TAU);
  ctx.fill();

  requestAnimationFrame(draw);
}

requestAnimationFrame(draw);
